import type { AnswerValue } from './types';
import { buildSentAnswers, competitorHostsOf } from './redact';

/** キーを並べ替えた JSON（同じ内容なら同じ文字列） */
export function canonicalJson(v: unknown): string {
  if (Array.isArray(v)) return `[${v.map(canonicalJson).join(',')}]`;
  if (v && typeof v === 'object') {
    const o = v as Record<string, unknown>;
    return `{${Object.keys(o).filter((k) => o[k] !== undefined).sort().map((k) => `${JSON.stringify(k)}:${canonicalJson(o[k])}`).join(',')}}`;
  }
  return JSON.stringify(v ?? null);
}

export async function sha256Hex(s: string): Promise<string> {
  const buf = await globalThis.crypto.subtle.digest('SHA-256', new TextEncoder().encode(s));
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

/** 送る内容（除去後の回答＋競合のホスト名）のハッシュ。除去で消える違い（電話番号の書き換えなど）は「変わった」に数えない */
export function answersHash(answers: Record<string, AnswerValue>): Promise<string> {
  return sha256Hex(canonicalJson({ v: 1, answers: buildSentAnswers(answers), competitors: competitorHostsOf(answers) }));
}

export interface AiConfigKey {
  model: string;
  promptVersion: string;
  effort: string;
  /**
   * 要件定義書のひな型と版（提案 v3 だけ。'TPL-WEB-REQ@0.1'。REQUIREMENTS_DOC_TEMPLATE.md §4.1）。
   * ひな型の版が上がれば同じ回答でも作り直せる。v2 は持たない（undefined は canonicalJson が落とすので v2 のハッシュは今と同じ）
   */
  template?: string;
}

export function configHash(c: AiConfigKey): Promise<string> {
  return sha256Hex(canonicalJson({ v: 1, model: c.model, promptVersion: c.promptVersion, effort: c.effort, template: c.template }));
}
